solution:
model LabTeam {
  id      Int         @id @default(autoincrement())
  name    String
  players LabPlayer[]
  @@map("lab_teams")
}

model LabPlayer {
  id     Int     @id @default(autoincrement())
  name   String
  teamId Int     @map("team_id")
  team   LabTeam @relation(fields: [teamId], references: [id])
  @@map("lab_players")
}

